const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const stage=$('.card-stage'),filter=$('#filter'),detail=$('#detail'),menu=$('#menu');
let active=0,subset=cards.map((_,i)=>i),lastFocus=null;
const escapeHtml=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){stage.innerHTML='';const n=subset.length;for(let k=Math.min(n,5)-1;k>=0;k--){let i=subset[(active+k)%n];let b=document.createElement('button');b.className='solution-card'+(k===0?' front':'');b.innerHTML=cards[i].html;b.setAttribute('aria-label','Open '+cards[i].name);b.tabIndex=k===0?0:-1;b.style.zIndex=10-k;const angles=[0,6,-10,17,-23],xs=[0,23,-30,45,-55];b.style.transform=`translateX(calc(-50% + ${xs[k]}px)) rotate(${angles[k]}deg) translateY(${-k*9}px)`;b.onclick=()=>{if(k){active=(active+k)%n;render()}else openDetail()};stage.append(b)}$('#count').textContent=`${active+1} / ${n}`;$('#prev').disabled=$('#next').disabled=n<2;}
function change(delta){active=(active+delta+subset.length)%subset.length;render();if(detail.open)fillDetail()}
function applyFilter(value){filter.value=value;subset=cards.map((_,i)=>i).filter(i=>value==='all'||cards[i].category===value);active=0;render()}
$('#prev').onclick=()=>change(-1);$('#next').onclick=()=>change(1);filter.onchange=()=>applyFilter(filter.value);
let startX=0;stage.addEventListener('pointerdown',e=>startX=e.clientX);stage.addEventListener('pointerup',e=>{const delta=e.clientX-startX;if(Math.abs(delta)>65)change(delta<0?1:-1)});
stage.addEventListener('pointermove',e=>{const b=$('.solution-card.front .wheel-card');if(!b)return;const r=b.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;for(const [key,val] of Object.entries({'--mx':x+'%','--my':y+'%','--bgx':x+'%','--bgy':y+'%','--active':'1'}))b.style.setProperty(key,val)});stage.addEventListener('pointerleave',()=>$('.solution-card.front .wheel-card')?.style.setProperty('--active','0'));
const summaries=[['Give clients convenience. Keep control.','Choose exactly which payment options appear on every invoice.','The right payment methods vary by client, matter, and firm policy. Turn card, ACH, or financing on or off for individual invoices, so every payment request fits.'],['See exactly where things stand.','From a morning brief of what’s due today to where your firm should grow next, Firm Agent answers it all in one conversation.','Firm Agent knows your whole firm and provides a complete morning brief, so you can proceed with the confidence that comes with staying on top of all tasks and deadlines.'],['Every detail surfaced.','Somewhere in your scanned files is the information you need. Discovery Assistant makes sure you find it.']];
function fillDetail(){const i=subset[active],c=cards[i],w=walkthroughs[i];$('.detail-content').innerHTML=`<div class="detail-hero"><div><div class="eyebrow">Fall ’26 · ${escapeHtml(c.name)}</div><h2>${escapeHtml(w.title||c.name)}</h2><p>${escapeHtml(w.tldr||c.subtitle)}</p></div>${c.html}</div>${w.media?`<img class="chapter-photo" src="${escapeHtml(w.media)}" alt="${escapeHtml(c.name)} product chapter" loading="lazy">`:''}<div class="detail-more"><h3>${escapeHtml(w.heading||c.name)}</h3><p>${escapeHtml(w.body||'')}</p></div><section class="walkthrough" aria-label="Feature walkthrough"><div class="walkthrough-tabs" role="tablist">${w.tabs.map((t,n)=>`<button role="tab" id="walk-tab-${n}" aria-controls="walk-panel" aria-selected="${n===0}" tabindex="${n===0?0:-1}"><span>0${n+1}</span>${escapeHtml(t.title||'')}</button>`).join('')}</div><div id="walk-panel" role="tabpanel" tabindex="0"></div></section>`;detail.setAttribute('aria-label',c.name);let tabIndex=0;const buttons=$$('.walkthrough-tabs button');function selectTab(n){tabIndex=(n+buttons.length)%buttons.length;buttons.forEach((b,j)=>{b.setAttribute('aria-selected',String(j===tabIndex));b.tabIndex=j===tabIndex?0:-1});const t=w.tabs[tabIndex];$('#walk-panel').setAttribute('aria-labelledby','walk-tab-'+tabIndex);$('#walk-panel').innerHTML=`<div class="step-label">FEATURE ${tabIndex+1} / ${w.tabs.length}</div><h3>${escapeHtml(t.title||'')}</h3><p>${escapeHtml(t.body||'')}</p><div class="walk-arrows"><button aria-label="Previous feature">←</button><button aria-label="Next feature">→</button></div>`;$('#walk-panel button[aria-label="Previous feature"]').onclick=()=>selectTab(tabIndex-1);$('#walk-panel button[aria-label="Next feature"]').onclick=()=>selectTab(tabIndex+1)}buttons.forEach((b,n)=>{b.onclick=()=>selectTab(n);b.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowRight'){e.preventDefault();e.stopPropagation();selectTab(n+1);buttons[tabIndex].focus()}if(e.key==='ArrowUp'||e.key==='ArrowLeft'){e.preventDefault();e.stopPropagation();selectTab(n-1);buttons[tabIndex].focus()}}});if(buttons.length)selectTab(0);detail.scrollTop=0;}
function openDetail(){lastFocus=document.activeElement;fillDetail();detail.showModal();document.body.style.overflow='hidden'}
function unlock(){document.body.style.overflow='';lastFocus?.focus()}
detail.addEventListener('close',unlock);menu.addEventListener('close',()=>{unlock();$('.nav-toggle').setAttribute('aria-expanded','false')});$('#detail .close').onclick=()=>detail.close();$('#detail-prev').onclick=()=>change(-1);$('#detail-next').onclick=()=>change(1);$('#detail-contact').onclick=()=>detail.close();$('.nav-toggle').onclick=()=>{lastFocus=document.activeElement;menu.showModal();document.body.style.overflow='hidden';$('.nav-toggle').setAttribute('aria-expanded','true')};$('#menu .close').onclick=()=>menu.close();$$('#menu a').forEach(a=>a.onclick=()=>{if(a.dataset.filter)applyFilter(a.dataset.filter);menu.close()});document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||menu.open||e.target.closest('.walkthrough'))return;if(e.key==='ArrowRight')change(1);if(e.key==='ArrowLeft')change(-1)});
$$('.integrations__slide-trigger').forEach(b=>{b.onclick=()=>{const selected=b.closest('.integrations__slide');$$('.integrations__slide').forEach(slide=>{const open=slide===selected;slide.classList.toggle('is-open',open);slide.querySelector('button').setAttribute('aria-expanded',String(open));slide.querySelector('.integrations__slide-body').setAttribute('aria-hidden',String(!open))})}});
const form=$('.closing__form');form.querySelectorAll('input').forEach(i=>i.required=true);form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const alert=form.querySelector('[role="alert"]');alert.style.color='#b8e6cb';alert.textContent='Demo complete — your details were validated locally. No enquiry has been sent.'});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let ticking=false,lastFrame=-1;const story=$('.story'),message=$('.story-message'),collage=$('.collage'),frame=$('#scroll-frame');
function onScroll(){ticking=false;if(reduced)return;const p=Math.max(0,Math.min(1,-story.getBoundingClientRect().top/(story.offsetHeight-innerHeight)));collage.style.transform=`scale(${1+p*.8}) rotate(${p*3}deg)`;message.style.transform=`scale(${1+Math.max(0,p-.2)*2})`;message.style.opacity=1-Math.max(0,(p-.45)*5);message.querySelector('p').style.opacity=Math.min(1,Math.max(0,(p-.15)*5));frame.style.opacity=Math.max(0,Math.min(1,(p-.48)*8));const idx=Math.min(frames.length-1,Math.floor(Math.max(0,(p-.48)/.52)*(frames.length-1)));if(idx!==lastFrame){frame.src=frames[idx];lastFrame=idx}}
addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(onScroll)}},{passive:true});addEventListener('resize',onScroll);render();onScroll();
